CA = 'Clinical application'
M = 'Management'
CARDS = {
'cp': [
(0, 'Definitions', 'Define cord presentation.', 'The umbilical cord lies below the presenting part while the membranes are intact.', 1),
(1, 'Definitions', 'Define cord prolapse.', 'The cord lies below the presenting part, in the vagina or outside the vulva, after the membranes have ruptured.', 1),
(2, 'Definitions', 'What is occult cord prolapse?', 'The cord lies beside the presenting part and is not felt on vaginal examination; it is suspected from fetal heart rate decelerations.', 2),
(3, 'Incidence', 'How common is cord prolapse?', 'About 1 in 300–500 deliveries.', 1),
(4, 'Risk factors', 'Which type of breech presentation carries the highest risk of cord prolapse?', 'Footling breech, about 15% (complete breech 5%, frank breech 0.5%).', 2),
(5, 'Risk factors', 'What are the risk factors for cord prolapse?', 'Malpresentation or unstable lie, prematurity, twin pregnancy (second twin), polyhydramnios, multiparity, and artificial rupture of membranes with a high head.', 2),
(6, 'Risk factors', 'Which procedure most often causes cord prolapse?', 'Artificial rupture of membranes when the presenting part is high and not engaged.', 1),
(7, 'Risk factors', 'Why does polyhydramnios cause cord prolapse?', 'The gush of liquor at rupture of membranes carries the cord down past a high presenting part.', 2),
(8, 'Risk factors', 'Is central placenta praevia a risk factor for cord prolapse?', 'No. Placenta praevia keeps the head high, but the os is covered by the placenta.', 3),
(9, 'Pathophysiology', 'What are the two mechanisms of fetal hypoxia in cord prolapse?', 'Compression of the cord between the presenting part and the pelvis, and spasm of the umbilical arteries caused by cold and handling.', 2),
(10, 'Diagnosis', 'What is the typical presentation of cord prolapse?', 'Sudden fetal bradycardia or variable decelerations immediately after spontaneous or artificial rupture of membranes; the mother is well, the liquor is clear and there is no bleeding.', 2),
(11, 'Diagnosis', 'The fetal heart rate falls suddenly immediately after rupture of membranes. What is the next step?', 'Immediate vaginal examination to exclude cord prolapse.', 2),
(12, 'Diagnosis', 'The cord is not pulsating on vaginal examination. Does this mean that the fetus is dead?', 'No, because arterial spasm is possible. The fetal heart is confirmed by Doppler or bedside ultrasound.', 3),
(13, 'Complications', 'What are the fetal complications of cord prolapse?', 'Asphyxia, fresh stillbirth, hypoxic brain injury, cerebral palsy, periventricular leukomalacia and birth trauma.', 2),
(14, M, 'What is the first action after diagnosing cord prolapse?', 'Call for help (obstetric, anaesthetic and neonatal teams), then push the presenting part up off the cord.', 1),
(15, M, 'Why should the cord not be handled?', 'Handling and cold cause spasm of the umbilical arteries and worsen hypoxia.', 2),
(16, M, 'Should the cord be pushed back into the uterus?', 'No. An exposed cord is only placed gently in the vagina with a warm, wet swab.', 2),
(17, M, 'How much saline is used to fill the bladder in cord prolapse?', 'About 500 mL of warm saline through a Foley catheter, which is then clamped.', 2),
(18, M, 'The bladder was filled for cord prolapse. What must be done before the uterine incision?', 'The catheter is unclamped and the bladder is emptied.', 3),
(19, M, 'Which maternal positions are used in cord prolapse?', 'The knee–chest position, or the exaggerated left Sims position (left lateral with the hips raised and the head down) for transfer.', 2),
(20, M, 'Which tocolytic is used in cord prolapse, and at what dose?', 'Terbutaline 0.25 mg subcutaneously, to stop the contractions compressing the cord.', 2),
(21, M, 'How is the baby delivered when the cord is pulsating and the cervix is 4 cm dilated?', 'By category 1 caesarean section.', 1),
(22, M, 'What is the target decision-to-delivery interval in cord prolapse?', '30 minutes or less.', 1),
(23, M, 'How is the baby delivered in cord prolapse at full dilatation with a low vertex?', 'By instrumental delivery (forceps or ventouse), if a quick delivery is likely.', 2),
(24, M, 'How is the baby delivered in cord prolapse at full dilatation with a transverse lie?', 'By caesarean section.', 2),
(25, M, 'How is delivery managed in cord prolapse when the fetus is dead?', 'Vaginal delivery; caesarean section is not performed for the baby.', 2),
(26, M, 'How is cord prolapse before 26 weeks managed?', 'It is managed as a miscarriage: vaginal delivery, without caesarean section.', 3),
(27, M, 'Why is the third stage actively managed after delivery for cord prolapse?', 'The risk of PPH is higher after tocolysis, caesarean section or instrumental delivery.', 3),
(28, 'Cord presentation', 'How is cord presentation at term managed?', 'Artificial rupture of membranes is avoided and the woman is counselled. Most cases end in caesarean section, because the cord prolapses when the membranes rupture.', 2),
(29, 'Prevention', 'How is artificial rupture of membranes performed safely in polyhydramnios?', 'As a controlled procedure in theatre, with the head held at the pelvic brim and the liquor released slowly.', 3),
],
'ui': [
(0, 'Definitions', 'Define uterine inversion.', 'The uterus turns inside out: the fundus descends into the uterine cavity, through the cervix or out of the vulva.', 1),
(1, 'Incidence', 'How common is uterine inversion?', 'About 1 in 2000–3000 deliveries; maternal mortality is up to 15%.', 1),
(2, 'Classification', 'What is first-degree uterine inversion?', 'The fundus inverts into the cavity but does not pass through the cervix.', 1),
(3, 'Classification', 'What is second-degree uterine inversion?', 'The fundus passes through the cervix and lies in the vagina.', 1),
(4, 'Classification', 'What is third-degree uterine inversion?', 'The fundus reaches or passes the vulva.', 1),
(5, 'Classification', 'What is fourth-degree (total) uterine inversion?', 'Both the uterus and the vagina are inverted outside the vulva.', 1),
(6, 'Classification', 'How is inversion classified by timing?', 'Acute: less than 24 hours; subacute: 24 hours to 4 weeks; chronic: more than 4 weeks after delivery.', 2),
(7, 'Classification', 'What is the commonest cause of chronic (non-puerperal) inversion?', 'A fundal submucous fibroid polyp that pulls the fundus down.', 2),
(8, 'Aetiology', 'What is the commonest cause of acute uterine inversion?', 'Cord traction before the placenta has separated, when the uterus is relaxed.', 1),
(9, 'Aetiology', 'What are the risk factors for uterine inversion?', 'Fundal placenta, short cord, uterine atony, placenta accreta, fundal pressure (Credé manoeuvre) and previous inversion.', 2),
(10, 'Clinical features', 'What is the commonest sign of acute uterine inversion?', 'Postpartum haemorrhage, in about 94% of cases.', 1),
(11, 'Clinical features', 'Why is the shock out of proportion to the blood loss?', 'Traction on the ovaries, tubes and peritoneum stimulates the vagus nerve, causing neurogenic shock with bradycardia.', 3),
(12, 'Clinical features', 'What is the abdominal finding in uterine inversion?', 'The fundus is absent, or there is a cup-shaped depression at the top of the uterus (first and second degree).', 2),
(13, 'Clinical features', 'What is the vaginal finding in uterine inversion?', 'A soft, purple-red mass in the vagina or at the vulva, sometimes with the placenta attached.', 2),
(14, 'Differential diagnosis', 'In PPH, how does the fundus distinguish atony from inversion?', 'A fundus that is palpable and soft indicates atonic PPH; an absent fundus with a vaginal mass indicates inversion.', 2),
(15, M, 'What is the first step in acute uterine inversion?', 'Call for help and replace the uterus immediately (Johnson manoeuvre), with the placenta left attached.', 1),
(16, M, 'Should the placenta be removed before the uterus is replaced?', 'No, because this causes very heavy bleeding. The uterus is replaced first and the placenta is removed afterwards.', 2),
(17, M, 'Describe the Johnson manoeuvre.', 'With the palm on the fundus, the uterus is pushed up through the cervix towards the umbilicus; the part that came out last is replaced first.', 2),
(18, M, 'An oxytocin infusion is running when inversion occurs. What is done?', 'The oxytocin infusion is stopped, because it tightens the cervical ring.', 3),
(19, M, 'Which drugs relax the cervical ring in uterine inversion?', 'Terbutaline 0.25 mg subcutaneously, magnesium sulphate 4 g IV over 15 minutes, or general anaesthesia with a volatile agent.', 3),
(20, M, 'How much blood is cross-matched in uterine inversion?', '4–6 units, with two large-bore cannulae inserted.', 2),
(21, M, "Describe O'Sullivan's method.", 'Hydrostatic replacement: 2–5 L of warm saline is run into the sealed vagina and pushes the fundus back.', 2),
(22, M, "What must be excluded before O'Sullivan's method?", 'Rupture of the uterus or vagina.', 3),
(23, M, 'What is the Huntington procedure?', 'At laparotomy, clamps are placed on the round ligaments inside the cup and the fundus is pulled up step by step.', 3),
(24, M, 'What is the Haultain procedure?', 'At laparotomy, a posterior incision through the tight cervical ring allows the uterus to be replaced.', 3),
(25, M, 'What are the steps after the uterus has been replaced?', 'The tocolytic is stopped, oxytocin 40 IU in 500 mL is given over 4 hours, the fist is kept in the fundus, and then the placenta is removed.', 3),
(26, M, 'Why are antibiotics given after uterine inversion?', 'Manual handling and a raw surface increase the risk of endometritis.', 2),
(27, 'Prevention', 'How is uterine inversion prevented?', 'Cord traction is applied only after the signs of placental separation, with suprapubic counter-pressure; fundal pressure is avoided.', 1),
],
'afe': [
(0, 'Definition', 'What is amniotic fluid embolism (AFE)?', 'Sudden maternal collapse in labour or soon after delivery, when amniotic fluid and fetal cells enter the maternal circulation.', 1),
(1, 'Incidence', 'How common is amniotic fluid embolism?', 'It is rare: about 1 in 8000 to 1 in 30 000 births. It is unpredictable and not preventable.', 1),
(2, 'Timing', 'When does amniotic fluid embolism most often occur?', 'In labour, around rupture of the membranes (70%); 19% occur at caesarean section and 11% within 48 hours after delivery.', 2),
(3, 'Risk factors', 'What are the risk factors for amniotic fluid embolism?', 'Induction or artificial rupture of membranes, caesarean or instrumental delivery, multiple pregnancy, polyhydramnios, advanced maternal age, placenta praevia, abruption and uterine rupture.', 2),
(4, 'Risk factors', 'Why is oxytocin avoided early in the evacuation of a molar pregnancy?', 'Contractions before the uterus is half emptied can force trophoblast and fluid into the veins, causing embolism.', 3),
(5, 'Pathophysiology', 'Is amniotic fluid embolism a mechanical embolus?', 'No. It is an anaphylactoid reaction to fetal material, which causes vasospasm and heart failure.', 2),
(6, 'Pathophysiology', 'What happens in phase 1 of amniotic fluid embolism?', 'Pulmonary vasospasm causes right and then left heart failure, leading to hypoxia, shock, convulsions and cardiac arrest within minutes.', 3),
(7, 'Pathophysiology', 'What happens in phase 2 of amniotic fluid embolism?', 'Tissue factor in the amniotic fluid triggers DIC, causing massive haemorrhage with uterine atony.', 3),
(8, 'DIC', 'How many cases of amniotic fluid embolism have DIC at presentation, and later?', '12% at presentation; almost all survivors develop DIC within 4 hours.', 3),
(9, 'Clinical features', 'What is the classic clinical picture of amniotic fluid embolism?', 'A woman in labour or just delivered develops sudden dyspnoea, hypoxia and hypotension or collapse, followed by bleeding from coagulopathy.', 1),
(10, 'Clinical features', 'What are the warning symptoms before collapse in amniotic fluid embolism?', 'Sudden breathlessness, chills, agitation and a feeling that something is wrong.', 2),
(11, 'Clinical features', 'What is the fetal sign of amniotic fluid embolism before delivery?', 'Sudden fetal bradycardia.', 1),
(12, 'Clinical features', 'Can bleeding be the first sign of amniotic fluid embolism?', 'Yes. In some women severe haemorrhage with DIC is the first sign.', 2),
(13, 'Investigations', 'What are the key investigations in suspected amniotic fluid embolism?', 'Arterial blood gas, full blood count, clotting screen with fibrinogen, bedside clotting test, urea and electrolytes, calcium, magnesium, cross-match, chest X-ray, ECG and echocardiography.', 2),
(14, 'Investigations', 'What are the chest X-ray and ECG findings in amniotic fluid embolism?', 'The chest X-ray shows pulmonary oedema; the ECG shows ischaemia and right heart strain.', 2),
(15, 'Diagnosis', 'How is amniotic fluid embolism diagnosed in a living patient?', 'Clinically, by exclusion; no test confirms it. Treatment is given without waiting for results.', 2),
(16, 'Diagnosis', 'What gives the definitive diagnosis of amniotic fluid embolism?', 'Post-mortem examination showing fetal squames and debris in the maternal pulmonary vessels.', 2),
(17, 'Diagnosis', 'What is the significance of fetal squames in pulmonary artery blood from a living woman?', 'The finding is supportive only and does not prove amniotic fluid embolism.', 3),
(18, 'Differential diagnosis', 'On postnatal day 5 a woman has pleuritic chest pain, a swollen calf and collapse. What is the diagnosis?', 'Pulmonary embolism; there is no early DIC, and it is confirmed by CT pulmonary angiography.', 2),
(19, 'Differential diagnosis', 'A woman collapses with convulsions and tinnitus after an epidural top-up. What is the treatment?', 'This is local anaesthetic toxicity: lipid emulsion 20%, 1.5 mL/kg IV.', 3),
(20, 'Differential diagnosis', 'A woman collapses with a rash and wheeze minutes after an IV antibiotic. Which drug is given?', 'This is anaphylaxis: adrenaline 0.5 mg IM.', 2),
(21, M, 'What is the first step when a woman collapses with suspected amniotic fluid embolism?', 'Call for help (resuscitation team), then secure the airway and give high-flow oxygen at 15 L/min.', 1),
(22, M, 'What is the CPR ratio in maternal cardiac arrest?', '30 compressions to 2 breaths, with the uterus displaced to the left.', 1),
(23, 'Perimortem caesarean section', 'When is perimortem caesarean section performed?', 'In cardiac arrest at 20 weeks or more: it is started at 4 minutes of CPR and the baby is delivered by 5 minutes, at the place of arrest.', 2),
(24, 'Perimortem caesarean section', 'What is the main purpose of perimortem caesarean section?', 'It removes uterine compression of the inferior vena cava and aorta so that CPR is effective; it is performed mainly for the mother.', 3),
(25, M, 'How is DIC treated in amniotic fluid embolism?', 'Blood, FFP 15 mL/kg, cryoprecipitate if fibrinogen is below 2 g/L, platelets if below 50 × 10⁹/L, and tranexamic acid 1 g IV.', 3),
(26, M, 'Which drugs are used for refractory hypotension in amniotic fluid embolism?', 'A vasopressor such as phenylephrine or noradrenaline, with or without an inotrope, in the intensive care unit.', 3),
(27, M, 'Why are IV fluids given with care in amniotic fluid embolism?', 'The right heart is failing, so large volumes cause pulmonary oedema.', 3),
(28, M, 'Which uterotonics are used for uterine atony in amniotic fluid embolism?', 'Oxytocin 40 IU in 500 mL over 4 hours and carboprost 250 µg IM; hysterectomy if bleeding persists.', 2),
(29, 'Prognosis', 'What is the prognosis of amniotic fluid embolism?', 'Maternal mortality is 13–80% in reported series, and up to 85% of survivors have hypoxic brain damage.', 2),
],
'sd': [
(0, 'Definition', 'Define shoulder dystocia.', 'After delivery of the head, the shoulders fail to deliver with gentle downward traction and additional manoeuvres are needed; the head-to-body interval exceeds 60 seconds.', 1),
(1, 'Incidence', 'How common is shoulder dystocia?', 'About 1 in 200 vaginal births.', 1),
(2, 'Mechanism', 'Which part is impacted in shoulder dystocia?', 'The anterior shoulder behind the symphysis pubis; rarely, the posterior shoulder on the sacral promontory.', 1),
(3, 'Mechanism', 'Why does episiotomy alone not relieve shoulder dystocia?', 'The obstruction is bony; episiotomy only provides room for internal manoeuvres.', 2),
(4, 'Mechanism', 'How fast does the fetal pH fall in shoulder dystocia?', 'By about 0.04 per minute; about 5 minutes is the longest that a baby tolerates.', 3),
(5, 'Risk factors', 'What are the antenatal risk factors for shoulder dystocia?', 'Previous shoulder dystocia, macrosomia, diabetes, BMI above 30, excessive weight gain, post-term pregnancy and anencephaly.', 2),
(6, 'Risk factors', 'What are the intrapartum risk factors for shoulder dystocia?', 'A prolonged late first stage or second stage, instrumental (mid-cavity) delivery, oxytocin augmentation and induction of labour.', 2),
(7, 'Risk factors', 'Why is diabetes a strong risk factor for shoulder dystocia?', 'Fetal insulin deposits fat on the shoulders and trunk, while the head remains of normal size.', 2),
(8, 'Risk factors', 'Can shoulder dystocia be predicted?', 'Poorly: about half of cases occur in babies under 4 kg, and the estimated weight on ultrasound may be wrong by 10–15%.', 3),
(9, 'Clinical features', 'What is the turtle sign?', 'The delivered head retracts tightly against the perineum; it indicates shoulder dystocia.', 1),
(10, 'Clinical features', 'What are the other signs of shoulder dystocia?', 'Slow delivery of the face and chin, absence of restitution, failure of gentle traction and a congested face.', 2),
(11, M, 'What is the mnemonic for the shoulder dystocia drill?', 'HELPERR: Help, Evaluate for episiotomy, Legs (McRoberts), suprapubic Pressure, Enter (internal manoeuvres), Remove the posterior arm, Roll onto all fours.', 1),
(12, M, 'What is the first manoeuvre after calling for help?', 'The McRoberts manoeuvre: the hips are hyperflexed and abducted, with the thighs on the abdomen.', 1),
(13, M, 'How does the McRoberts manoeuvre work?', 'It flattens the sacrum and rotates the symphysis pubis upwards, which frees the anterior shoulder.', 2),
(14, M, 'How is suprapubic pressure applied?', 'An assistant presses downwards and laterally from the side of the fetal back, behind the anterior shoulder; the pressure is steady and then rocking.', 2),
(15, M, 'What proportion of babies deliver with McRoberts and suprapubic pressure?', 'About 80%.', 1),
(16, M, 'How long is each manoeuvre attempted?', 'For 30–60 seconds, before moving on to the next.', 2),
(17, 'Manoeuvres', 'Describe the Rubin II manoeuvre.', 'Fingers placed on the back of the anterior shoulder push it towards the chest and into the oblique diameter.', 3),
(18, 'Manoeuvres', 'Describe the Woods screw manoeuvre.', 'Rubin II combined with pressure on the front of the posterior shoulder to rotate the shoulders.', 3),
(19, 'Manoeuvres', 'How does delivery of the posterior arm help?', 'It reduces the shoulder-to-shoulder width to the shoulder-to-axilla width.', 3),
(20, 'Manoeuvres', 'What is the Gaskin manoeuvre?', 'The mother is rolled onto all fours and the manoeuvres are repeated.', 2),
(21, 'Last resort', 'Name three last-resort measures in shoulder dystocia.', 'Deliberate fracture of the clavicle, the Zavanelli manoeuvre (replacement of the head followed by caesarean section) and symphysiotomy.', 2),
(22, 'Last resort', 'What is the Zavanelli manoeuvre?', 'The head is pushed back into the vagina, with terbutaline 0.25 mg subcutaneously, and the baby is delivered by caesarean section.', 2),
(23, 'Contraindicated actions', 'Which two actions are contraindicated in shoulder dystocia?', 'Fundal pressure, and strong or lateral traction on the head.', 1),
(24, 'Complications', 'What is the commonest fetal injury after shoulder dystocia?', "Brachial plexus injury, usually Erb's palsy (C5–C6).", 1),
(25, 'Complications', "What is the clinical picture of Erb's palsy?", "The arm is limp and internally rotated, with the elbow extended and the wrist flexed (waiter's tip position); the grasp reflex is present.", 2),
(26, 'Complications', "What is the clinical picture of Klumpke's palsy?", 'It affects C8–T1: claw hand, absent grasp reflex and sometimes Horner syndrome.', 3),
(27, 'Complications', 'What are the maternal complications of shoulder dystocia?', 'PPH, third- and fourth-degree perineal tears, cervical and vaginal tears, uterine rupture (after fundal pressure) and bladder injury.', 2),
(28, 'Aftercare', 'How is PPH prevented after shoulder dystocia?', 'Active management of the third stage, with oxytocin 40 IU in 500 mL over 4 hours.', 2),
(29, 'Prevention', 'When is elective caesarean section offered for macrosomia?', 'When the estimated fetal weight exceeds 4.5 kg in a diabetic woman or 5 kg in a non-diabetic woman.', 2),
(30, 'Prevention', 'What is the recurrence risk of shoulder dystocia?', 'About 1 in 10; the mode of delivery is discussed with an experienced team.', 2),
(31, CA, 'Which fetal anomaly classically causes shoulder dystocia?', 'Anencephaly.', 3),
(33, CA, 'What is the commonest maternal complication of shoulder dystocia?', 'Postpartum haemorrhage.', 1),
]}
QS = {
'cp-1': dict(d=2, stem='A para 4 woman at 40 weeks with known polyhydramnios is in labour at 6 cm. The membranes rupture with a large gush, and within a minute the fetal heart rate falls to 70 bpm and remains there. She has no pain other than her contractions, there is no bleeding and the liquor is clear.', why='Rupture of the membranes followed by sudden bradycardia, in a well mother with clear liquor, is the classic picture of cord prolapse. Vasa praevia also follows rupture of membranes, but with fresh bleeding.'),
'cp-2': dict(d=2, stem='A para 3 woman at 39 weeks is 5 cm dilated. Artificial rupture of membranes is performed for slow progress; two minutes later the fetal heart rate is 80 bpm. On vaginal examination a pulsating loop of cord lies in the vagina below the head.', why='Calling for help and elevating the presenting part relieve the pressure on the cord and gain time for delivery. Replacing the cord causes spasm and is never attempted.'),
'cp-3': dict(d=2, stem='A para 2 woman at 38 weeks is in early labour at 4 cm with intact membranes. On vaginal examination a soft, pulsating cord is felt through the membranes in front of the head. The CTG is normal.', why='Cord presentation in labour is managed by caesarean section, because the cord prolapses as soon as the membranes rupture. Artificial rupture of membranes is contraindicated.'),
'cp-4': dict(d=2, stem='A primigravida at 40 weeks has been fully dilated for 50 minutes, with the vertex occipito-anterior at station +2. The membranes rupture and the fetal heart rate falls to 90 bpm. A pulsating loop of cord is felt beside the head.', q='What is the best mode of delivery?', why='At full dilatation with a low head, instrumental delivery is quicker than caesarean section. Caesarean section is chosen when the head is high or the lie is not cephalic.'),
'cp-5': dict(d=3, stem='A para 5 woman at 39 weeks is fully dilated. The head is 4/5 palpable above the pelvic brim. After spontaneous rupture of membranes a pulsating cord is seen at the vulva and the fetal heart rate is 85 bpm.', why='Even at full dilatation, a high, unengaged head cannot be delivered safely vaginally, so caesarean section is required. Ventouse delivery requires an engaged head.'),
'cp-6': dict(d=2, stem='A para 3 woman at 37 weeks arrives from a village 3 hours after her membranes ruptured. A loop of cord is hanging out of the vulva; it is cold and not pulsating. Bedside ultrasound shows no fetal heart activity.', why='Once fetal death is confirmed there is no fetal indication for caesarean section, so she delivers vaginally. Caesarean section would only add maternal risk.'),
'cp-7': dict(d=3, stem='A para 2 woman at 38 weeks is 3 cm dilated. Cord prolapse is found after spontaneous rupture of membranes. The cord is limp and no pulsation is felt, but bedside ultrasound shows a fetal heart rate of 90 bpm.', why='A cord without pulsation may be in spasm; fetal heart activity on ultrasound shows that the fetus is alive. A live fetus with a cervix that is not fully dilated requires a category 1 caesarean section.'),
'cp-8': dict(d=3, stem='A para 4 woman at 38 weeks is in a rural health centre. Cord prolapse is found at 4 cm with a pulsating cord. The nearest operating theatre is 90 minutes away by ambulance, and the midwife cannot keep her hand in the vagina for the whole journey.', why='A full bladder lifts the presenting part off the cord, and the left Sims position is safe in a moving vehicle. The knee–chest position is unsafe in an ambulance.'),
'cp-9': dict(d=3, stem='A para 2 woman at 39 weeks has cord prolapse at 5 cm. A Foley catheter was used to fill her bladder before transfer. She is now on the operating table under general anaesthesia and the surgeon has opened the abdomen.', why='The full bladder lies in front of the lower uterine segment and is at risk of injury, so it is emptied before the uterus is opened.'),
'cp-10': dict(d=2, stem='A para 3 woman at 39 weeks is 4 cm dilated. A pulsating loop of cord is in the vagina and the presenting part is being held up. The theatre will be ready in 15 minutes. She is contracting strongly every 2 minutes, and the fetal heart rate falls to 80 bpm with each contraction.', why='Subcutaneous terbutaline acts within minutes and stops the contractions pressing the head onto the cord. Oral nifedipine acts too slowly for an emergency.'),
'cp-11': dict(d=2, stem='Five women with intact membranes are reviewed in the antenatal clinic.', q='Which woman has the highest risk of cord prolapse if her membranes rupture?', why='Footling breech carries a risk of about 15%, compared with about 5% for complete breech and 0.5% for frank breech. An engaged head fills the pelvis and protects the cord.'),
'cp-12': dict(d=3, stem='A para 6 woman at 38 weeks has polyhydramnios. The lie was transverse, then oblique, then cephalic at three successive visits. Today it is cephalic with a high head, and induction of labour is planned.', q='What is the safest method of rupturing her membranes?', why='With polyhydramnios and a high head, controlled artificial rupture of membranes in theatre releases the liquor slowly and allows immediate caesarean section if the cord prolapses.'),
'cp-13': dict(d=2, stem='A para 5 woman is 37 weeks pregnant. At the last three visits the fetus was transverse, breech and then cephalic. She lives two hours from the hospital.', why='A woman with an unstable lie is admitted from 37 weeks, because cord prolapse after rupture of membranes at home would be fatal for the baby. Artificial rupture of membranes with a high, changing lie causes cord prolapse.'),
'cp-14': dict(d=3, stem='A para 2 woman with preterm prelabour rupture of membranes at 24 weeks is now in labour at 6 cm, and a pulsating loop of cord is felt in the vagina. The fetal heart rate is 140 bpm on Doppler.', why='Before 26 weeks, cord prolapse is managed as a miscarriage and delivery is vaginal. Caesarean section adds maternal risk when the baby has very little chance of survival.'),
'ui-1': dict(d=2, stem='A para 2 woman delivered 10 minutes ago; the intern pulled hard on the cord before any sign of placental separation. She now has severe lower abdominal pain and feels faint. Her pulse is 54/min, blood pressure 75/40 mmHg and blood loss about 400 mL. The fundus cannot be felt on abdominal palpation.', why='Pain in the third stage with shock out of proportion to the blood loss, bradycardia and an absent fundus are the classic signs of uterine inversion. Atony gives a soft fundus that is easily palpable.'),
'ui-2': dict(d=2, stem='A para 3 woman is in shock a few minutes after delivery. There is a dark-red, rounded mass at the introitus with the placenta still attached to it, and no fundus is palpable abdominally. Help has been called and two cannulae are in place.', why='The uterus is replaced immediately with the placenta left in place. Removing the placenta first exposes the placental bed and causes very heavy bleeding.'),
'ui-3': dict(d=3, stem='Twenty minutes after delivery, the uterus of a para 4 woman is inverted into the vagina. Two attempts at manual replacement have failed because a tight cervical ring does not allow the fundus through. There is no sign of a tear.', why='A tight ring is relaxed with a tocolytic or a volatile anaesthetic before replacement is attempted again. Oxytocic drugs tighten the ring and are withheld until after replacement.'),
'ui-4': dict(d=2, stem="In a para 2 woman, an inverted uterus has been replaced manually after terbutaline 0.25 mg subcutaneously. The placenta is still attached and the doctor's fist is inside the fundus.", q='Which drug should be started now?', why='Once the uterus has been replaced, the tocolytic is stopped and oxytocin is given to contract the uterus, hold it in place and control bleeding.'),
'ui-5': dict(d=3, stem='In a para 3 woman the inverted uterus reaches the vulva. Manual replacement has failed despite terbutaline. The team plans to run warm saline rapidly into the vagina while sealing the labia with a silicone ventouse cup.', why="Hydrostatic (O'Sullivan) replacement requires an intact genital tract; if there is a rupture the saline escapes into the peritoneal cavity and the method fails."),
'ui-6': dict(d=1, stem='Fifteen minutes after delivery a para 2 woman has heavy bleeding and pain. The fundus is not palpable abdominally. On vaginal examination a soft, purple mass has passed through the cervix and lies in the vagina, but it does not reach the vulva.', q='Which degree of inversion is this?', why='In second-degree inversion the fundus has passed through the cervix but remains in the vagina. In third-degree inversion it reaches or passes the vulva.'),
'ui-7': dict(d=3, stem='Six weeks after a home delivery, a para 4 woman has irregular bleeding, an offensive discharge and a haemoglobin of 7 g/dL. Speculum examination shows a red mass in the vagina; no stalk can be felt around it. On bimanual examination there is no fundus, only a cup-shaped depression at the top.', why='An absent fundus with a cup-shaped depression and a mass in the vagina indicate chronic inversion. A fibroid polyp has a stalk, and a normal fundus is palpable above it.'),
'ui-8': dict(d=2, stem='A para 2 woman has just delivered. She has severe pain and a blood pressure of 80/50 mmHg. No fundus is palpable abdominally and a purple mass lies at the introitus. The house officer wishes to arrange an ultrasound scan before any treatment.', why='Acute inversion is a clinical diagnosis, and with every minute the cervical ring tightens. Four to six units of blood are cross-matched at the same time. Ultrasound is reserved for unclear subacute or chronic cases.'),
'ui-9': dict(d=3, stem='Five minutes after delivery a para 3 woman suddenly becomes pale and clammy. Her pulse is 50/min and blood pressure 70/40 mmHg, with a blood loss of only 300 mL. No fundus is palpable and a red mass is seen in the vagina.', q='What best explains her bradycardia?', why='Traction on the structures drawn into the ring triggers neurogenic shock with bradycardia. Blood loss alone causes tachycardia.'),
'ui-10': dict(d=1, stem='Midwives are being taught how to manage the third stage of labour after oxytocin 10 IU IM.', q='Which practice best prevents uterine inversion?', why='Waiting for the signs of separation and applying suprapubic counter-pressure prevent the fundus from being pulled down. Traction before separation is the commonest cause of inversion.'),
'ui-11': dict(d=2, stem='A para 4 woman books at 10 weeks. At her last delivery at home, the uterus inverted after the cord was pulled and was replaced in hospital.', why='Inversion can recur, so she should deliver in hospital with active management of the third stage and resuscitation facilities ready. Caesarean section is not indicated for this reason.'),
'ui-12': dict(d=3, stem='Five days after a home delivery, a para 3 woman is brought with a fever of 38.7 °C, offensive discharge and a haemoglobin of 8 g/dL. A swollen red mass fills the vagina; the fundus is not palpable and the cervical ring is tight and oedematous.', why='In subacute inversion the ring is fixed and the uterus is oedematous and infected, so manual replacement rarely succeeds. Shock and infection are treated first, and the uterus is then replaced under general anaesthesia, often by the Huntington or Haultain procedure.'),
'ui-13': dict(d=3, stem='A para 2 woman delivers in a village with a trained midwife. Immediately after forceful cord traction she collapses, and a red mass appears at the vulva with the placenta attached. One immediate attempt at replacement has failed. The hospital is 2 hours away.', why='In the community one early attempt at replacement is made; if it fails, the uterus is protected, the woman is resuscitated and she is transferred lying flat with the placenta attached. Removing the placenta causes massive bleeding.'),
'afe-1': dict(d=2, stem='A 38-year-old para 5 woman at 39 weeks is on an oxytocin infusion for induction of labour. Ten minutes after artificial rupture of membranes at 6 cm she says that something is wrong, becomes breathless and cyanosed, and has a convulsion. Her oxygen saturation is 78% and blood pressure 70/30 mmHg. An hour later blood continues to ooze from her cannula sites.', why='Sudden hypoxia and collapse around rupture of the membranes, followed by DIC, is the classic picture of amniotic fluid embolism. Pulmonary embolism rarely causes early DIC and usually occurs after delivery.'),
'afe-2': dict(d=2, stem='A para 3 woman in labour at 7 cm suddenly becomes breathless and agitated. She is cyanosed, with an oxygen saturation of 80%, pulse 130/min and blood pressure 75/40 mmHg. She is still breathing and has a pulse. Help has been called.', why='Oxygen and displacement of the uterus off the inferior vena cava maintain life in the first minutes. Large volumes of fluid cause pulmonary oedema when the right heart is failing.'),
'afe-3': dict(d=2, stem='A para 2 woman at 36 weeks collapses in labour after sudden breathlessness and is now in cardiac arrest. CPR at 30:2 with left uterine displacement has continued for 4 minutes with no cardiac output.', why='From 20 weeks, perimortem caesarean section is started at 4 minutes and the baby should be delivered by 5 minutes. Transfer wastes time and interrupts CPR.'),
'afe-4': dict(d=3, stem='A para 1 woman at 16 weeks has a cardiac arrest during surgical evacuation for a missed miscarriage. CPR has been in progress for 4 minutes.', why='Before 20 weeks the uterus is too small to compress the inferior vena cava, so emptying it does not improve CPR. The 4-minute rule applies only from 20 weeks.'),
'afe-5': dict(d=3, why='Perimortem caesarean section is performed mainly for the mother: venous return increases and chest compressions become effective. Fetal survival is a secondary benefit.'),
'afe-6': dict(d=3, stem='A para 4 woman survived a sudden collapse in labour and was delivered by caesarean section. She is now bleeding from the wound and cannula sites. Her platelet count is 90 × 10⁹/L, fibrinogen 1.2 g/L and prothrombin time prolonged. FFP 15 mL/kg is being given.', why='A fibrinogen level below 2 g/L is the indication for cryoprecipitate. Platelets are given when the count is below 50 × 10⁹/L.'),
'afe-7': dict(d=2, stem='A para 3 woman collapsed with cyanosis during labour in a rural hospital that has no laboratory. She has now delivered and is bleeding from the uterus and puncture sites.', q='Which bedside test best demonstrates a clotting failure?', why='The bedside clotting test is quick and reliable: failure to form a clot within 7–10 minutes indicates DIC. Blood products are given without waiting for laboratory results.'),
'afe-8': dict(d=3, stem='A para 2 woman is intubated and receiving oxygen after a sudden collapse in labour. After a careful 1 L fluid bolus her blood pressure is 70/40 mmHg, the JVP is raised and echocardiography shows a dilated right ventricle.', why='Hypotension after fluids with a failing right heart requires a vasopressor, with or without an inotrope. Further fluid worsens right heart failure and pulmonary oedema.'),
'afe-9': dict(d=2, stem='A para 1 woman in labour at 5 cm, with membranes ruptured for 20 hours, is given ampicillin 2 g IV. Ten minutes later she is breathless, with wheeze, urticaria and swollen lips. Her blood pressure is 80/50 mmHg.', why='Collapse with a rash and wheeze immediately after a drug is anaphylaxis, and intramuscular adrenaline is the first-line treatment. Steroids and antihistamines are adjuncts only.'),
'afe-10': dict(d=3, stem='A para 2 woman is in labour with an epidural. Two minutes after a top-up she reports tingling around the mouth and ringing in the ears, and then has a convulsion. Her blood pressure is 85/50 mmHg.', why='Perioral tingling and tinnitus after an epidural top-up suggest local anaesthetic toxicity, which is treated with 20% lipid emulsion. Magnesium sulphate is used for an eclamptic convulsion.'),
'afe-11': dict(d=2, why='Only fetal squames in the pulmonary vessels at post-mortem examination are diagnostic. Squames in blood from a pulmonary artery catheter in a living woman are supportive only, because they are also found in normal women.'),
'afe-12': dict(d=2, stem='On day 5 after an emergency caesarean section, a para 2 woman has sudden pleuritic chest pain and breathlessness. Her left calf is swollen. Her oxygen saturation is 90%, pulse 115/min and blood pressure 110/70 mmHg. There is no bleeding and the clotting screen is normal.', why='Postnatal pleuritic pain with a swollen calf and no early DIC suggests pulmonary embolism, which is confirmed by CT pulmonary angiography and treated with heparin.'),
'afe-13': dict(d=2, stem='A para 4 woman had a sudden collapse at delivery and is now stable with intensive care support; FFP and cryoprecipitate have been given. The uterus is soft and bleeding continues despite an oxytocin infusion of 40 IU in 500 mL. She does not have asthma.', why='For atony that persists after oxytocin, carboprost 250 µg IM is the next uterotonic. Terbutaline relaxes the uterus and would increase the bleeding.'),
'afe-14': dict(d=3, stem='A para 3 woman is in a rural hospital that has no blood components. After a sudden collapse with cyanosis in labour she is delivered, but she bleeds from multiple sites and her blood does not clot.', q='Which is the best practical replacement in this setting?', why='Fresh whole blood provides red cells, clotting factors and platelets when components are not available. Large volumes of crystalloid dilute the clotting factors and cause pulmonary oedema.'),
'afe-15': dict(d=2, stem='A para 1 woman survived a sudden collapse with cyanosis and DIC in labour. Before discharge she asks about her next pregnancy.', why='Recurrence is rare, so a further pregnancy is not contraindicated, but she should deliver where intensive care support is available. Amniotic fluid embolism cannot be prevented by caesarean section or drugs.'),
'sd-1': dict(d=1, stem='A primigravida at 41 weeks has gestational diabetes treated with insulin. After a 3-hour second stage the head delivers slowly and then retracts tightly against the perineum. Restitution does not occur, and gentle downward traction with the next contraction fails.', why='The McRoberts manoeuvre (hips hyperflexed onto the abdomen) is the first manoeuvre; with suprapubic pressure it is successful in about 80% of cases. Episiotomy only provides room for the hands and does not release the shoulder.'),
'sd-2': dict(d=2, stem='A para 2 woman at 40 weeks has an estimated fetal weight of 4.2 kg. The head has delivered but the shoulders are impacted. Help has arrived, she is lying flat with her thighs flexed onto her abdomen, and routine traction has failed.', why='The McRoberts manoeuvre is followed by suprapubic pressure (Rubin I) on the back of the anterior shoulder. Fundal pressure impacts the shoulder further against the symphysis pubis.'),
'sd-3': dict(d=2, stem='A para 3 woman is 41 weeks pregnant. The shoulders are impacted after delivery of the head. The McRoberts manoeuvre and suprapubic pressure have each been tried for 60 seconds without success. The baby is alive and the theatre is not yet ready.', why='After the McRoberts manoeuvre and suprapubic pressure, the internal manoeuvres follow; delivery of the posterior arm reduces the width of the shoulders. The Zavanelli manoeuvre and symphysiotomy are last resorts.'),
'sd-4': dict(d=1, stem="In a para 2 woman the shoulders do not follow after delivery of the head. One midwife flexes the woman's hips, a doctor applies suprapubic pressure, a student pushes on the fundus and another doctor performs an episiotomy.", why='Fundal pressure impacts the shoulder further and can cause uterine rupture and brachial plexus injury, so it is never used.'),
'sd-5': dict(d=2, why='The McRoberts manoeuvre straightens the lumbosacral angle and rotates the symphysis pubis upwards over the anterior shoulder; it does not change the bony diameters of the pelvis.'),
'sd-6': dict(d=3, stem="The head has delivered and the shoulders are impacted; the McRoberts position has been adopted. The fetal back is on the mother's left (left occipito-anterior). The assistant is about to apply suprapubic pressure.", why='Pressure on the back of the anterior shoulder, applied from the side of the fetal back, adducts the shoulder into the oblique diameter. Fundal pressure is contraindicated.'),
'sd-7': dict(d=2, stem='A 4.6 kg baby was born after a difficult delivery with strong traction on the head. The right arm lies limp and internally rotated, with the elbow extended and the wrist flexed. The grasp reflex is present but the Moro reflex is absent on the right.', why="The waiter's tip position with a preserved grasp reflex indicates Erb's palsy, caused by stretching of C5–C6. Injury to C8–T1 gives a claw hand with an absent grasp reflex."),
'sd-8': dict(d=3, stem='A 4.4 kg baby is born after shoulder dystocia. The left hand is clawed with no grasp reflex. The left eyelid droops and the left pupil is small.', why="A claw hand with ptosis and a small pupil indicates a lower brachial plexus injury that involves the sympathetic chain. In Erb's palsy the grasp reflex is preserved."),
'sd-9': dict(d=2, stem='A para 3 woman at 41 weeks delivers a 4.3 kg baby after a long induced labour; the McRoberts manoeuvre, suprapubic pressure and delivery of the posterior arm were needed. The placenta has been delivered complete.', why='Postpartum haemorrhage is the commonest maternal complication of shoulder dystocia and results from atony and tears. An oxytocin infusion is started and the whole genital tract is examined.'),
'sd-10': dict(d=2, stem='A para 2 woman with pre-existing type 2 diabetes treated with insulin is 38 weeks pregnant. The estimated fetal weight on ultrasound is 4.7 kg. Her previous baby weighed 3.6 kg and was born by normal delivery.', why='In a diabetic woman an estimated fetal weight above 4.5 kg is an indication for elective caesarean section to avoid shoulder dystocia. In a non-diabetic woman the threshold is 5 kg.'),
'sd-11': dict(d=3, stem='A para 1 woman with gestational diabetes well controlled on metformin is 37 weeks pregnant. The estimated fetal weight is 4.2 kg. She has no other problems.', why='With good control and an estimated fetal weight below 4.5 kg, caesarean section is not automatically indicated; she delivers at 38–39 weeks in hospital. Waiting beyond term increases fetal size and risk.'),
'sd-12': dict(d=3, stem='A para 4 woman is 42 weeks pregnant. The head was delivered 5 minutes ago. The McRoberts manoeuvre, suprapubic pressure, internal rotation, delivery of the posterior arm and the all-fours position have all failed. The baby is still alive and the theatre next door is ready.', why='When all the HELPERR steps have failed and a theatre is ready, the Zavanelli manoeuvre (cephalic replacement) under tocolysis followed by caesarean section is chosen.'),
'sd-13': dict(d=3, stem="A para 3 woman is in a peripheral hospital far from any operating theatre. The baby's head delivered 6 minutes ago, and every manoeuvre, including delivery of the posterior arm and the all-fours position, has failed. The fetal heart is still heard.", why='Where caesarean section is not available nearby, symphysiotomy is a life-saving last resort for a live baby. Cleidotomy is reserved for a dead baby.'),
'sd-14': dict(d=3, stem='A para 5 woman has shoulder dystocia. All manoeuvres have failed, and no fetal heart has been detected on Doppler for the last 5 minutes.', why='When the baby is dead, the aim is to protect the mother, so the clavicles are divided (cleidotomy). Symphysiotomy and caesarean section expose her to risk without fetal benefit.'),
'sd-15': dict(d=1, stem="A para 1 woman had shoulder dystocia at her first delivery; the baby had an Erb's palsy that recovered. She is now 30 weeks pregnant and asks whether it can happen again.", why='The recurrence rate after a previous shoulder dystocia is about 1 in 10, so the mode of delivery is discussed with an experienced team. The background rate is 1 in 200.'),
'afe-emq1#0': dict(d=1, stem='Thirty minutes after a normal delivery a para 6 woman is in shock, with a blood pressure of 80/50 mmHg and a pulse of 128/min. The fundus is soft, at the level of the umbilicus, and clots are expelled when it is rubbed.', why='A soft fundus that becomes firm when rubbed indicates atony; the shock corresponds to the blood loss and there is tachycardia.'),
'afe-emq1#1': dict(d=2, stem='A para 3 woman with a previous caesarean section is induced with oxytocin. At 8 cm she has sudden severe pain, the contractions stop, the head recedes out of the pelvis and fetal parts are palpable under the abdominal wall. Her pulse is 140/min.', why='A uterine scar, sudden pain, cessation of contractions and recession of the head indicate uterine rupture.'),
'afe-emq1#2': dict(d=2, stem='Two hours after delivery with repair of a second-degree tear, a para 2 woman has severe perineal pain and cannot pass urine. Her pulse is 120/min and the fundus is firm. A tense, tender swelling bulges from the right vaginal wall.', why='A firm uterus with a tense, painful swelling of the vaginal wall and shock indicates a haematoma, often beneath the repair.'),
'afe-emq1#3': dict(d=3, stem='A para 1 woman at 39 weeks is in labour at 7 cm with clear liquor. Minutes after artificial rupture of membranes she becomes agitated, cyanosed and hypotensive, and then has a convulsion. Her blood pressure had been 110/70 mmHg and there was no proteinuria. Later she oozes continuously from the cannula sites.', why='Hypoxia and collapse around rupture of the membranes, followed by DIC, with a previously normal blood pressure, indicate amniotic fluid embolism and not eclampsia.'),
'sd-emq2#0': dict(d=1, stem='The head of a 4.3 kg baby delivered 20 seconds ago and has retracted against the perineum. Help has just arrived and the woman is lying on her back with her legs in stirrups.', why='After calling for help, the first step is to lay the woman flat and hyperflex her hips (McRoberts manoeuvre).'),
'sd-emq2#1': dict(d=3, stem='A theatre next door is ready. Every manoeuvre, including the all-fours position, has failed; the baby is alive and the head was delivered 5 minutes ago.', why='When a theatre is ready, the head is replaced under terbutaline and caesarean section is performed (Zavanelli manoeuvre).'),
'sd-emq2#2': dict(d=3, stem='In a peripheral unit with no operating theatre within 3 hours, all manoeuvres have failed and the fetal heart is still heard.', why='Where caesarean section is not available nearby, symphysiotomy under local anaesthesia can save a live baby.'),
'sd-emq2#3': dict(d=3, why='When the baby is dead, division of the clavicles (cleidotomy) protects the mother from further trauma.'),
'cp-emq3#0': dict(d=2, stem='A para 1 woman at 32 weeks is not in labour and has intact membranes. Ultrasound and vaginal examination show a loop of cord lying below the breech. The CTG is normal.', why='Preterm cord presentation with intact membranes is managed conservatively, and artificial rupture of membranes is avoided.'),
'cp-emq3#1': dict(d=2, stem='A para 4 woman in a rural health centre is 3 cm dilated with a pulsating cord in the vagina; the referral hospital is 2 hours away by road.', why='A full bladder keeps the presenting part elevated during a long transfer; the knee–chest position is unsafe in a vehicle.'),
'cp-emq3#2': dict(d=3, stem='In a para 3 woman the uterus is inverted to the vulva after the third stage. Manual replacement failed even after terbutaline; examination shows no tear in the vagina or uterus.', why='When manual replacement has failed and rupture has been excluded, hydrostatic pressure with warm saline can replace the fundus.'),
'cp-emq3#3': dict(d=3, stem='A para 5 woman is undergoing laparotomy for uterine inversion. Clamps on the round ligaments cannot pull the fundus up through a very tight ring.', why='When the ring is too tight, a posterior incision through it (Haultain procedure) allows replacement, followed by repair.'),
}
